@DisplayName("주문을 생성하면 총 금액이 계산된다")
@Test
void createOrder() {
    // given
    cafeKiosk.add(new Americano(), 1);
    cafeKiosk.add(new Latte(), 1);

    // when
    Order order = cafeKiosk.createOrder(영업중);

    // then
    assertThat(order.getTotalPrice()).isEqualTo(8500);
    assertThat(order.getBeverages()).hasSize(2);
    assertThat(order.getStatus()).isEqualTo(OrderStatus.INIT);
}

